def solve(s):
    k = 2
    counts = {}
    left = 0
    longest = 0

    for right, char in enumerate(s):
        counts[char] = counts.get(char, 0) + 1

        while len(counts) > k:
            left_char = s[left]
            counts[left_char] -= 1
            if counts[left_char] == 0:
                del counts[left_char]
            left += 1

        longest = max(longest, right - left + 1)

    return longest

